u = User.find_by(email: "garveyindustry5@gmail.com")
raise "USER_MISMATCH" unless u && u.external_id == "5129068866782" && u.username == "garveycraft5"
raise "SUSPENDED" if u.suspended?
raise "FEATURE_OFF" unless Feature.active?(:custom_html_pages, u)
l = Link.where(unique_permalink: "qkicyh").first
raise "LINK_MISMATCH" unless l && l.id == 15024361 && l.alive?
raise "PRE_NOT_EMPTY link" unless l.custom_html.to_s.empty?
raise "PRE_PAGE_EXISTS" unless Page.where(pageable_type: "Link", pageable_id: l.id).count == 0
raise "DATA_URI" if PAY.include?("data:image")
raise "MARKER" unless PAY.include?(%q{data-gv-page="flipmode-v1"})
raise "BUY" unless PAY.scan(%q{data-gumroad-action="buy"}).size == 2
raise "PRICE" unless PAY.scan(%q{data-gumroad-field="price"}).size == 2
raise "TOO_BIG" if PAY.length > Page::MAX_CUSTOM_HTML_LENGTH
san = Ai::PageSanitizer.sanitize_with_report(PAY)
out = san.html
raise "SANITIZER_DIRTY #{san.report.inspect}" unless san.report[:total_removed] == 0 && san.report[:removed_tags].empty?
raise "NOT_IDEMPOTENT" unless Ai::PageSanitizer.sanitize(out) == out
puts "EXPECT_SHA16=#{Digest::SHA256.hexdigest(out)[0,16]} EXPECT_LEN=#{out.length}"
res = Pages::CustomHtmlWriter.replace!(l, PAY)
puts "VALID=#{res.valid?} ERRORS=#{res.errors.full_messages.inspect}"
raise "WRITE_INVALID" unless res.valid?
pg = Page.where(pageable_type: "Link", pageable_id: l.id).order(:id).last
raise "NO_PAGE" unless pg
stored = pg.reload.custom_html.to_s
raise "LEN_MISMATCH #{stored.length} vs #{out.length}" unless stored.length == out.length
raise "BYTES_MISMATCH" unless Digest::SHA256.hexdigest(stored) == Digest::SHA256.hexdigest(out)
raise "MARKER_GONE" unless stored.include?("flipmode-v1")
puts "WROTE page_id=#{pg.id} slug=#{pg.slug.inspect} len=#{stored.length} POST_SHA16=#{Digest::SHA256.hexdigest(stored)[0,16]}"
puts "BUY=#{stored.scan(%q{data-gumroad-action="buy"}).size} PRICE=#{stored.scan(%q{data-gumroad-field="price"}).size} IMG=#{stored.scan("<img").size}"
puts "VISIBLE=#{u.custom_landing_page_visible? rescue "n/a"}"
